import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useColors } from 'vuestic-ui'
import mapboxgl from 'mapbox-gl'
import MapboxGeocoder from '@mapbox/mapbox-gl-geocoder'
import {
  addBuildingLayers,
  buildingLayers,
  CONCORDIA_SOURCE_ID,
  setBuildingVisibility,
} from './layer/buildingLayers.js'

import tileZones from './layer/montrealTiles.json'
import {
  addMapOverlays,
  createTileZoneData,
  mapOverlays,
  setOverlayVisibility,
  TILE_ZONE_FILL_ID,
} from './layer/mapOverlays.js'
import { getBuildingDetails } from './layer/featureDetails.js'
import { getShadingLighting, preserveMapBrightness } from './layer/shading.js'

const zoneData = createTileZoneData(tileZones)

/** Basemap URL là style Mapbox; đổi style không làm đổi dataset Concordia. */
const mapStyles = [
  { title: 'Streets', value: 'mapbox://styles/mapbox/streets-v11' },
  { title: 'Outdoors', value: 'mapbox://styles/mapbox/outdoors-v11' },
  { title: 'Light', value: 'mapbox://styles/mapbox/light-v10' },
  { title: 'Dark', value: 'mapbox://styles/mapbox/dark-v10' },
  { title: 'Satellite Streets', value: 'mapbox://styles/mapbox/satellite-streets-v11' },
  { title: 'Navigation Day', value: 'mapbox://styles/mapbox/navigation-day-v1' },
  { title: 'Navigation Night', value: 'mapbox://styles/mapbox/navigation-night-v1' },
]

/**
 * Quản lý toàn bộ vòng đời bản đồ City; gọi đồng bộ từ <script setup>.
 *
 * Input:
 * - VITE_MAPBOX_TOKEN trong .env.local: public token pk. có quyền đọc dịch vụ.
 * - View gắn mapElement vào div bản đồ, controlsElement vào toolbar Vue.
 * - Theme Vuestic cung cấp màu HUD; không tự đổi basemap theo theme.
 *
 * Output: các Vue ref/reactive để view bind bằng v-model, không trả Mapbox Map
 * ra ngoài để tránh proxy hóa WebGL và tránh nhiều nơi cùng quản lý vòng đời.
 *
 * Ví dụ trong view:
 *   const { mapElement, mapStyle, layerVisibility } = useCityMap()
 *   layerVisibility['city-concordia-2d'] = true
 * Kết quả: watcher đổi visibility của layer 2D; 3D vẫn giữ lựa chọn riêng.
 * mapStyle.value = 'mapbox://styles/mapbox/light-v10' tải nền mới rồi tự phục hồi
 * ba layer. Concordia 3D mặc định bật; 2D và OSM 3D mặc định tắt như dự án cũ.
 *
 * Các trường trả về chính:
 * - mapElement/controlsElement: Ref<HTMLElement|null>, view gắn qua ref.
 * - initialized: đã tạo Mapbox; ready: đã cài layer cho style hiện tại,
 *   chưa có nghĩa tất cả tiles trong vùng nhìn đã tải xong.
 * - mapStyle/layersOpen/controlsVisible: Ref chọn nền, mở menu nền và ẩn controls.
 *   Building HUD luôn hiện, không phụ thuộc layersOpen hay controlsVisible.
 * - layerVisibility: Reactive<Record<layerId, boolean>>, ví dụ 2D=true.
 * - layerErrors: Reactive<Record<layerId, string>>, lỗi từng lớp/nguồn.
 * - enabledLayerCount: số lựa chọn đang bật trong HUD Layer (building, overlays, Shading); không phải số feature đã tải.
 * - error/searchError: lỗi nền và tìm kiếm; layerErrorMessages gộp lỗi nguồn.
 * - isDark: màu theme để HUD/biểu tượng hỗ trợ cả dark và light.
 *
 * State chỉ tồn tại trong lần mở trang: chuyển route sẽ hủy map/control/observer;
 * quay lại khởi tạo mới. Popup/overlays/Shading được dọn cùng map; không chạy solver.
 * - popupElement: DOM Vue cho Popup.setDOMContent; selectedFeature.rows chỉ chứa text.
 * - overlayVisibility/overlayErrors: state theo contours/tileZones; không dùng chung building count.
 * - shading: ngày/giờ địa phương, enabled và sunlight; sunPosition dùng độ theo SunCalc 2.x.
 * - originalLights giữ cấu hình nền để tắt Shading trả lại ánh sáng cũ.
 */
export function useCityMap() {
  const mapElement = ref(null)
  const controlsElement = ref(null)
  const popupElement = ref(null)
  const selectedFeature = ref(null)
  const initialized = ref(false)
  const ready = ref(false)
  const error = ref('')
  const searchError = ref('')
  const controlsVisible = ref(true)
  const layersOpen = ref(false)
  const mapStyle = ref('mapbox://styles/mapbox/dark-v10')
  const layerVisibility = reactive(Object.fromEntries(buildingLayers.map((entry) => [entry.id, entry.defaultVisible])))
  const layerErrors = reactive({})
  const overlayVisibility = reactive(Object.fromEntries(mapOverlays.map((entry) => [entry.id, entry.defaultVisible])))
  const overlayErrors = reactive({})
  const localNow = new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString()
  const shading = reactive({
    enabled: false,
    date: localNow.slice(0, 10),
    time: localNow.slice(11, 16),
    sunlight: false,
  })
  /**
   * VaDateInput/VaTimeInput nhận Date theo giờ địa phương; logic Shading giữ chuỗi
   * YYYY-MM-DD/HH:mm. Hai computed chỉ đổi định dạng ở ranh giới UI, không đổi UTC.
   * Ví dụ chọn 21/06/2026 và 09:30 -> shading.date="2026-06-21", time="09:30".
   * Clear trả chuỗi rỗng để validator báo lỗi; không âm thầm dùng ngày/giờ hiện tại.
   * Ngày picker dùng 12:00, giờ picker dùng 01/01/2000 để tách việc chọn từng phần;
   * parseShadingDate vẫn kiểm tra DST trên ngày + giờ thực sự do người dùng chọn.
   */
  const shadingDate = computed({
    get: () => (shading.date ? new Date(shading.date + 'T12:00:00') : null),
    set: (value) => {
      shading.date = value
        ? new Date(value.getTime() - value.getTimezoneOffset() * 60000).toISOString().slice(0, 10)
        : ''
    },
  })
  const shadingTime = computed({
    get: () => (shading.time ? new Date('2000-01-01T' + shading.time + ':00') : null),
    set: (value) => {
      shading.time = value ? value.toTimeString().slice(0, 5) : ''
    },
  })
  const sunPosition = ref(null)
  const shadingError = ref('')
  const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone
  const shadingLayers = computed(() =>
    buildingLayers.filter(
      (entry) => entry.layer.type === 'fill-extrusion' && layerVisibility[entry.id] && !layerErrors[entry.id],
    ),
  )
  const enabledLayerCount = computed(
    () =>
      Object.values(layerVisibility).filter(Boolean).length +
      Object.values(overlayVisibility).filter(Boolean).length +
      Number(shading.enabled),
  )
  const layerErrorMessages = computed(() => [...new Set(Object.values(layerErrors))])
  const { currentPresetName } = useColors()
  const isDark = computed(() => currentPresetName.value === 'dark')
  const accessToken = import.meta.env.VITE_MAPBOX_TOKEN?.trim()
  let map, resizeObserver, popup
  let originalLights = null
  let originalSurfacePaint = []
  let shadingApplied = false

  /** Output: đóng popup và xóa lựa chọn; gọi khi click trống, Escape hoặc đổi style. */
  function closeFeature() {
    selectedFeature.value = null
    popup?.remove()
  }

  /**
   * Output: bỏ ánh sáng 3D do Shading thêm rồi khôi phục cấu hình gốc của style.
   * Mapbox 3 trả [{type:'flat', ...}] cho nền cũ, nhưng setLights(flat) chỉ cập nhật
   * ánh sáng legacy, KHÔNG gỡ ambient/directional. Phải clear bằng null trước;
   * nếu không, tắt công tắc mà hình ảnh vẫn bị chiếu sáng bởi Shading.
   */
  function restoreShadingLighting() {
    if (!shadingApplied) return
    map.setLights(null)
    if (originalLights) map.setLights(originalLights)
    for (const [id, property, value] of originalSurfacePaint) {
      if (map.getLayer(id)) map.setPaintProperty(id, property, value)
    }
    originalSurfacePaint = []
    shadingApplied = false
  }

  /**
   * Input: shading từ HUD + tâm map hiện tại. Output: setLights và sunPosition.
   * Khi tắt hoặc input lỗi, trả đúng ánh sáng của style trước khi bật Shading.
   * Chỉ chạy khi style sẵn sàng; không đọc painter/sourceCaches/buffer nội bộ.
   */
  function applyShading() {
    if (!map || !ready.value) return
    shadingError.value = ''
    if (!shading.enabled) {
      restoreShadingLighting()
      sunPosition.value = null
      return
    }
    try {
      const result = getShadingLighting(shading, map.getCenter().wrap())
      if (!shadingApplied) originalSurfacePaint = preserveMapBrightness(map)
      map.setLights(result.lights)
      sunPosition.value = result.position
      shadingApplied = true
    } catch {
      restoreShadingLighting()
      sunPosition.value = null
      shadingError.value = 'Choose a valid local date and time (1950 or later).'
    }
  }

  /** Input: điểm pixel từ click/mousemove. Output: building ưu tiên trước vùng tiles. */
  function featureAt(point) {
    if (!map || !ready.value) return null
    const ids = [...buildingLayers.map((entry) => entry.id), TILE_ZONE_FILL_ID].filter((id) => map.getLayer(id))
    const features = map.queryRenderedFeatures(point, { layers: ids })
    return features.find((feature) => feature.layer.id !== TILE_ZONE_FILL_ID) || features[0] || null
  }

  watch(shading, applyShading)
  watch(overlayVisibility, () => {
    if (map && ready.value) setOverlayVisibility(map, overlayVisibility)
    if (selectedFeature.value?.kind === 'zone' && !overlayVisibility.tileZones) closeFeature()
  })

  /**
   * Input: style URL mới từ VaSelect. Output: style cũ được thay hoàn toàn;
   * ready=false khóa công tắc trong lúc style đang tải. Giữ layerVisibility
   * để style.load khôi phục đúng lựa chọn thay vì reset về mặc định.
   */
  watch(mapStyle, (style) => {
    if (!map) return
    closeFeature()
    ready.value = false
    error.value = ''
    for (const id of Object.keys(layerErrors)) delete layerErrors[id]
    for (const id of Object.keys(overlayErrors)) delete overlayErrors[id]
    map.setStyle(style, { diff: false })
  })

  /**
   * Input: thay đổi boolean, ví dụ OSM false -> true. Output: cập nhật layer
   * đã dựng. Nếu style chưa sẵn sàng, không gọi API Mapbox; state vẫn được lưu.
   */
  watch(layerVisibility, () => {
    if (map && ready.value) setBuildingVisibility(map, layerVisibility)
    if (selectedFeature.value?.kind === 'building' && !layerVisibility[selectedFeature.value.layerId]) closeFeature()
  })

  onMounted(() => {
    if (!accessToken?.startsWith('pk.')) {
      error.value = 'Set VITE_MAPBOX_TOKEN to a public Mapbox token (pk.) and restart the dev server.'
      return
    }
    try {
      // Tọa độ theo WGS84 [longitude, latitude], zoom 11 tại Montréal.
      map = new mapboxgl.Map({
        container: mapElement.value,
        accessToken,
        style: mapStyle.value,
        center: [-73.5673, 45.5017],
        zoom: 11,
        pitch: 0,
        bearing: 0,
        antialias: true,
        attributionControl: false,
      })
      initialized.value = true

      /**
       * Input: style.load ban đầu hoặc sau setStyle. Output: source/layer được
       * tạo lại và ready=true. Một basemap thiếu OSM không chặn Concordia.
       */
      map.on('style.load', () => {
        try {
          addMapOverlays(map, overlayVisibility, zoneData)
          Object.assign(layerErrors, addBuildingLayers(map, layerVisibility))
        } catch {
          error.value = 'Could not initialize map layers. Try another basemap.'
        }
        originalLights = map.getLights()
        originalSurfacePaint = []
        shadingApplied = false
        ready.value = true
        applyShading()
      })

      /**
       * Input ví dụ: { sourceId: 'city-concordia', error: Error('403 ...') }.
       * Output: đánh dấu cả hai lớp Concordia không tải được, vẫn giữ basemap
       * và OSM hoạt động. Không đưa raw error/URL lên UI vì có thể chứa token.
       */
      map.on('error', (event) => {
        if (event.sourceId === CONCORDIA_SOURCE_ID) {
          const message = 'Concordia data could not be loaded. Check access to this dataset.'
          for (const entry of buildingLayers) {
            if (entry.layer.source === CONCORDIA_SOURCE_ID) layerErrors[entry.id] = message
          }
          return
        }
        const overlay = mapOverlays.find((entry) => entry.sourceIds.includes(event.sourceId))
        if (overlay) {
          overlayErrors[overlay.id] = 'Could not load ' + overlay.label.toLowerCase() + '. Check source access.'
          return
        }
        error.value = 'Could not load Mapbox. Check your token, connection and allowed domains.'
      })

      // Vue giữ DOM popup; Mapbox chỉ đặt nó tại tọa độ click. Không ghép HTML từ properties.
      popup = new mapboxgl.Popup({ closeButton: false, closeOnClick: false, maxWidth: '320px', focusAfterOpen: false })
      popup.on('close', () => {
        selectedFeature.value = null
      })
      map.on('click', async (event) => {
        const feature = featureAt(event.point)
        closeFeature()
        if (!feature) return
        const building = buildingLayers.find((entry) => entry.id === feature.layer.id)
        selectedFeature.value = building
          ? {
              kind: 'building',
              layerId: building.id,
              title: building.label,
              rows: getBuildingDetails(feature.properties),
            }
          : {
              kind: 'zone',
              title: 'Zone ' + feature.properties.zone,
              rows: [
                { label: 'Grid', value: 'Montréal' },
                { label: 'Tile package', value: 'Unavailable' },
              ],
            }
        const selection = selectedFeature.value
        await nextTick()
        // Bỏ click cũ nếu route đã đóng hoặc có click mới trong lúc Vue cập nhật DOM.
        if (!map || selectedFeature.value !== selection) return
        popup.setDOMContent(popupElement.value).setLngLat(event.lngLat).addTo(map)
      })
      map.on('mousemove', (event) => {
        map.getCanvas().style.cursor = featureAt(event.point) ? 'pointer' : ''
      })
      map.on('movestart', closeFeature)
      map.on('moveend', applyShading)

      // Geocoder nhận chuỗi địa điểm và tự xử lý gợi ý/marker/flyTo khi chọn.
      // Handler error ngăn EventEmitter phát lỗi không được xử lý khi API từ chối.
      const geocoder = new MapboxGeocoder({ accessToken, mapboxgl, placeholder: 'Search address or place' })
      geocoder.on('loading', () => (searchError.value = ''))
      geocoder.on('clear', () => (searchError.value = ''))
      geocoder.on('error', () => {
        searchError.value = 'Could not search locations. Check your token and connection.'
      })
      map.addControl(geocoder, 'top-right')
      map.addControl(new mapboxgl.NavigationControl(), 'top-right')

      // Input: DOM toolbar đã được Vue render. Output: Mapbox xếp toolbar cùng
      // search/zoom; khi map.remove(), onRemove tháo node trước khi Vue unmount.
      map.addControl(
        {
          onAdd: () => controlsElement.value,
          onRemove: () => controlsElement.value?.remove(),
        },
        'top-right',
      )
      map.addControl(new mapboxgl.AttributionControl({ compact: false }), 'bottom-right')

      // Thay đổi kích thước div -> resize canvas, kể cả khi sidebar mở/đóng.
      resizeObserver = new ResizeObserver(() => map?.resize())
      resizeObserver.observe(mapElement.value)
    } catch {
      error.value = 'Could not initialize Mapbox. Check your token and browser WebGL support.'
    }
  })

  /** Output khi rời route: ngừng observer, hủy map, worker và mọi control. */
  onBeforeUnmount(() => {
    resizeObserver?.disconnect()
    closeFeature()
    map?.remove()
    map = null
  })

  return {
    mapElement,
    controlsElement,
    popupElement,
    selectedFeature,
    closeFeature,
    mapOverlays,
    overlayVisibility,
    overlayErrors,
    shading,
    shadingDate,
    shadingTime,
    sunPosition,
    shadingError,
    shadingLayers,
    timeZone,
    initialized,
    ready,
    error,
    searchError,
    controlsVisible,
    layersOpen,
    mapStyle,
    mapStyles,
    buildingLayers,
    layerVisibility,
    layerErrors,
    layerErrorMessages,
    enabledLayerCount,
    isDark,
  }
}
