<script setup>
import { useCityMap } from './cityMap.js'
import 'mapbox-gl/dist/mapbox-gl.css'
import '@mapbox/mapbox-gl-geocoder/dist/mapbox-gl-geocoder.css'
import 'ionicons/dist/css/ionicons.min.css'

const {
  mapElement,
  controlsElement,
  popupElement,
  selectedFeature,
  closeFeature,
  mapOverlays,
  overlayVisibility,
  overlayErrors,
  shading,
  shadingDate,
  shadingTime,
  sunPosition,
  shadingError,
  shadingLayers,
  timeZone,
  initialized,
  ready,
  error,
  searchError,
  controlsVisible,
  layersOpen,
  mapStyle,
  mapStyles,
  buildingLayers,
  layerVisibility,
  layerErrors,
  layerErrorMessages,
  enabledLayerCount,
  isDark,
} = useCityMap()
</script>

<template>
  <section
    class="city-map-shell relative h-full min-h-0"
    :class="{ 'city-map-shell--light': !isDark }"
    @keydown.esc="closeFeature"
