            v-model="mapStyle"
            label="Basemap"
            aria-label="Map style"
            text-by="title"
            value-by="value"
            :options="mapStyles"
          />
        </VaDropdownContent>
      </VaDropdown>
      <VaButton
        class="city-glass"
        color="backgroundElement"
        text-color="textPrimary"
        size="small"
        :icon="controlsVisible ? 'ion-md-eye' : 'ion-md-eye-off'"
        :aria-pressed="!controlsVisible"
        :aria-label="controlsVisible ? 'Hide map controls' : 'Show map controls'"
        :title="controlsVisible ? 'Hide map controls' : 'Show map controls'"
        @click="controlsVisible = !controlsVisible"
      />
    </aside>
    <div class="city-hud-stack">
      <VaCard
        id="city-layer-hud"
        tag="aside"
        class="city-glass"
        color="backgroundElement"
        text-color="textPrimary"
        aria-labelledby="city-layer-title"
      >
        <VaCardTitle class="justify-between gap-2 !p-3 !pb-2">
          <h2 id="city-layer-title" class="text-xs font-semibold normal-case tracking-normal">Layer</h2>
          <VaChip
            size="small"
            color="primary"
            text-color="textPrimary"
            flat
            readonly
            :aria-label="enabledLayerCount + ' layers enabled'"
          >
            <!-- {{ enabledLayerCount }}/{{ buildingLayers.length + mapOverlays.length + 1 }} -->
          </VaChip>
        </VaCardTitle>
        <VaCardContent class="!p-3 !pt-0">
          <VaList class="space-y-1">
            <VaListItem
              v-for="entry in buildingLayers"
              :key="entry.id"
              class="city-building-row rounded-md p-2"
              :class="{ 'bg-backgroundPrimary': layerVisibility[entry.id] && !layerErrors[entry.id] }"
              :data-testid="'layer-' + entry.id"
              tabindex="-1"
            >
              <VaListItemSection>
                <VaListItemLabel :lines="2" class="text-xs font-semibold" :title="entry.description">
