            v-for="message in [...layerErrorMessages, ...Object.values(overlayErrors)]"
            :key="message"
            color="danger"
            dense
            outline
            class="mt-2 mb-0 text-xs"
            >{{ message }}</VaAlert
          >
        </VaCardContent>
      </VaCard>
