        v-if="shading.enabled"
        tag="aside"
        class="city-glass city-shading-hud"
        color="backgroundElement"
        text-color="textPrimary"
        aria-labelledby="city-shading-title"
      >
        <VaCardTitle class="!p-3 !pb-2"
